<div class="page-heading narrow"><h1>Site settings</h1></div><form method="post" class="form-panel narrow"><?=csrf()?><?php foreach(['archive_days'=>['Inactivity archive threshold (days)','60'],'max_file_mb'=>['Maximum file size in MB (1–10)','10'],'max_total_mb'=>['Maximum submission attachments in MB (1–25)','25'],'submission_limit'=>['Public submissions per IP per hour','12']] as $key=>$info) field($info[0],$key,setting($key,$info[1]),'number',true); field('Homepage title','home_title',setting('home_title',HOME_TITLE),'text',true); field('Homepage introduction','home_intro',setting('home_intro',HOME_INTRO),'textarea',true); field('Request-related notification template','notice_template',setting('notice_template','An administrator has reviewed your research request. Open your private management link to view its status.'),'textarea',true); ?><?php select_field('Email delivery adapter','mail_driver',['file'=>'Private file sink (local development)','mail'=>'Server mail (configure and verify host delivery first)'],setting('mail_driver',env('MAIL_DRIVER','file'))); field('Email sender address','mail_from',setting('mail_from',env('MAIL_FROM','noreply@example.invalid')),'email',true); ?><label class="check"><input type="checkbox" name="maintenance" <?=setting('maintenance','0')==='1'?'checked':''?>> Enable maintenance mode (public pages unavailable)</label><button>Save site settings</button><p class="fine">The server mail adapter uses the hosting mail configuration. SMTP credentials are never entered here. HTTPS, session lifetime and database secrets remain environment-only.</p></form>